apply="begin;\nset local lock_timeout='5s';\ndo $create_release$ begin\n"+guard+'\n'+pre+'execute $ddl$'+ddl+'$ddl$;\n'+post+"\nend $create_release$;\nnotify pgrst,'reload schema';\ncommit;\n";(p/'apply_prod.sql').write_text(apply)
